const root = $input.first().json;
const body = root.body || root;

try {
  const event = String(body.event || '').toLowerCase();
  const payload = body.payload || body.data || body;

  if (event && event !== 'message' && !event.includes('messages.upsert') && !event.includes('messages_upsert')) {
    return [];
  }

  if (payload && (payload.from || payload._data)) {
    if (payload.fromMe === true) return [];
    const fromRaw = String(payload.from || '');
    if (!fromRaw || fromRaw.includes('@g.us') || fromRaw === 'status@broadcast' || fromRaw.includes('status@broadcast')) return [];

    // WAHA chatId: usar el from completo (@c.us o @lid)
    const chatId = fromRaw;
    const phone = fromRaw
      .replace(/@c\.us$/i, '')
      .replace(/@s\.whatsapp\.net$/i, '')
      .replace(/@lid$/i, '')
      .split(':')[0];

    const texto = String(payload.body || payload.caption || '').trim();
    if (!phone || !texto) return [];

    return [{
      json: {
        canal: 'whatsapp',
        chat_id: chatId,
        dedupe_key: 'whatsapp:' + chatId,
        lead_name: payload.notifyName || payload._data?.notifyName || 'Cliente',
        phone: phone,
        mensaje: texto,
        waba_message_id: payload.id || '',
        fecha: new Date().toISOString(),
      },
    }];
  }

  const key = payload.key || {};
  if (key.fromMe === true) return [];
  const remoteJid = String(key.remoteJid || '');
  if (!remoteJid || remoteJid.includes('@g.us')) return [];
  const chatId = remoteJid;
  const phone = remoteJid.replace(/@s\.whatsapp\.net$/i, '').replace(/@c\.us$/i, '').replace(/@lid$/i, '').split(':')[0];
  const msg = payload.message || {};
  const texto = msg.conversation || msg.extendedTextMessage?.text || '';
  if (!phone || !String(texto).trim()) return [];
  return [{
    json: {
      canal: 'whatsapp',
      chat_id: chatId,
      dedupe_key: 'whatsapp:' + chatId,
      lead_name: payload.pushName || 'Cliente',
      phone: phone,
      mensaje: String(texto).trim(),
      waba_message_id: key.id || '',
      fecha: new Date().toISOString(),
    },
  }];
} catch (e) {
  return [];
}

const prep = $('Code - Normalizar WhatsApp').item.json;

let row = {};
try {
  row = $('Google Sheets - Buscar Lead').first().json || {};
} catch (e) {
  row = {};
}

const msg = String(prep.mensaje || '').trim();
const historialPrev = String(row.historial || '').trim();
const isKnownLead = Boolean(
  row.chat_id &&
    (historialPrev ||
      row.temperature ||
      row.status === 'abierto' ||
      row.estado_seguimiento === 'ninguno' ||
      row.estado_seguimiento === 'enviado_1' ||
      row.estado_seguimiento === 'respondido')
);

const INTENT = /\b(depto|departamento|casa|lote|local|oficina|alquiler|alquilo|alquilar|comprar|compra|venta|vender|propiedad|inmueble|inmobiliaria|presupuesto|habitaci[oó]n|dormitorio|ambientes|m2|zona|barrio|mendoza|godoy|cruz|lujan|nodo)\b/i;
const PERSONAL = /\b(hermano|hermana|mam[aá]|pap[aá]|partido|jueguito|f[uú]tbol|asado|salimos|birra|tomamos|llamame al personal|no es por una propiedad)\b/i;

let should_reply = true;
let skip_reason = '';
if (PERSONAL.test(msg) && !INTENT.test(msg)) {
  should_reply = false;
  skip_reason = 'mensaje_personal';
} else if (!isKnownLead && !INTENT.test(msg)) {
  should_reply = false;
  skip_reason = 'sin_intencion_inmobiliaria';
}

const datosPrev = {
  operacion: row.operacion || '',
  tipo_propiedad: row.tipo_propiedad || '',
  zona: row.zona || '',
  presupuesto: row.presupuesto || '',
  dormitorios: row.dormitorios || '',
};
const ultima_prev = row.ultima_actualizacion || row.last_interaction_at || row.updated_at || '';
const consultas_count_prev = row.consultas_count || '0';

const historialBlock = historialPrev ? historialPrev : '(Sin historial previo. Es el primer contacto calificado.)';

const prompt = `Sos el asistente virtual oficial de la inmobiliaria "Nodo Propiedades" (Mendoza, Argentina).
Atendes por WhatsApp. Tono: profesional, claro, cordial, rioplatense neutro. Maximo 1 emoji si aporta.

OBJETIVO: calificar el lead y pedir SOLO la info necesaria para un asesor humano.

DATOS A COMPLETAR (una pregunta por turno):
1) operacion: alquiler | compra | venta
2) tipo_propiedad: depto | casa | lote | local | oficina | otro
3) zona / barrio
4) presupuesto (o rango)
5) dormitorios / ambientes
6) urgencia

REGLAS:
- Usa el HISTORIAL: no repitas preguntas ya respondidas.
- Una pregunta concreta por mensaje.
- 2 a 4 oraciones.
- Si el tema no es inmobiliario pero hay historial, reconducilo.
- Si hay datos casi completos, resume y avisá que un asesor contactará.
- No inventes propiedades ni precios.

DATOS YA CARGADOS:
${JSON.stringify(datosPrev)}

HISTORIAL:
${historialBlock}

CLIENTE: ${prep.lead_name}
MENSAJE ACTUAL: "${msg}"

Responde SOLO JSON valido:
{"temperatura":"frio|tibio|caliente","intencion":"frase corta","operacion":"","tipo_propiedad":"","zona":"","presupuesto":"","dormitorios":"","lead_completo":false,"respuesta":"mensaje para el cliente"}`;

return [{
  json: {
    ...prep,
    isKnownLead,
    should_reply,
    skip_reason,
    historial_prev: historialPrev,
    ultima_prev,
    consultas_count_prev,
    operacion_prev: datosPrev.operacion,
    tipo_prev: datosPrev.tipo_propiedad,
    zona_prev: datosPrev.zona,
    presupuesto_prev: datosPrev.presupuesto,
    dormitorios_prev: datosPrev.dormitorios,
    prompt_groq: prompt,
  },
}];

const textoIA = ($json.text || '').trim();
const prep = $('Code - Armar Prompt').item.json;

let temperatura = 'frio';
let intencion = 'consulta general';
let respuesta = 'Hola, gracias por escribir a Nodo Propiedades. Para orientarte mejor: buscas alquilar o comprar, y en que zona?';
let operacion = prep.operacion_prev || '';
let tipo_propiedad = prep.tipo_prev || '';
let zona = prep.zona_prev || '';
let presupuesto = prep.presupuesto_prev || '';
let dormitorios = prep.dormitorios_prev || '';
let lead_completo = false;

try {
  const match = textoIA.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    temperatura = parsed.temperatura || temperatura;
    intencion = parsed.intencion || intencion;
    respuesta = parsed.respuesta || respuesta;
    operacion = parsed.operacion || operacion;
    tipo_propiedad = parsed.tipo_propiedad || tipo_propiedad;
    zona = parsed.zona || zona;
    presupuesto = parsed.presupuesto || presupuesto;
    dormitorios = parsed.dormitorios || dormitorios;
    lead_completo = Boolean(parsed.lead_completo);
  }
} catch (e) {}

const lineCliente = 'Cliente: ' + String(prep.mensaje || '').trim();
const lineBot = 'Bot: ' + String(respuesta || '').trim();
const prev = String(prep.historial_prev || '').trim();
let historial = prev ? prev + '\n' + lineCliente + '\n' + lineBot : lineCliente + '\n' + lineBot;
const lines = historial.split('\n').filter(Boolean);
if (lines.length > 24) historial = lines.slice(-24).join('\n');

const now = new Date();
const lastRaw = prep.ultima_prev || prep.fecha || '';
const lastTs = lastRaw ? new Date(lastRaw).getTime() : 0;
const daysGap = lastTs ? (now.getTime() - lastTs) / (1000 * 60 * 60 * 24) : 999;
const changedProperty =
  (zona && prep.zona_prev && zona.toLowerCase() !== String(prep.zona_prev).toLowerCase()) ||
  (tipo_propiedad && prep.tipo_prev && tipo_propiedad.toLowerCase() !== String(prep.tipo_prev).toLowerCase()) ||
  (operacion && prep.operacion_prev && operacion.toLowerCase() !== String(prep.operacion_prev).toLowerCase());
const esNuevaConsulta = !prep.isKnownLead || daysGap >= 14 || Boolean(changedProperty) ? 'si' : 'no';

const y = now.getFullYear();
const m = String(now.getMonth() + 1).padStart(2, '0');
const d = String(now.getDate()).padStart(2, '0');
const hh = String(now.getHours()).padStart(2, '0');
const mm = String(now.getMinutes()).padStart(2, '0');
const fechaLocal = y + '-' + m + '-' + d + ' ' + hh + ':' + mm;
const mes = y + '-' + m;
const consultaId = 'c_' + String(prep.phone || 'x').slice(-8) + '_' + now.toISOString().replace(/[-:TZ.]/g, '').slice(0, 14);
const prevCount = Number(prep.consultas_count_prev || 0) || 0;
const consultas_count = esNuevaConsulta === 'si' ? prevCount + 1 : Math.max(prevCount, 1);

return [{
  json: {
    canal: prep.canal,
    chat_id: prep.chat_id,
    dedupe_key: prep.dedupe_key,
    lead_name: prep.lead_name,
    phone: prep.phone,
    mensaje: prep.mensaje,
    waba_message_id: prep.waba_message_id,
    fecha: now.toISOString(),
    fecha_local: fechaLocal,
    mes: mes,
    anio: String(y),
    consulta_id: consultaId,
    es_nueva_consulta: esNuevaConsulta,
    consultas_count: String(consultas_count),
    temperatura,
    intencion,
    respuesta_wa: respuesta,
    operacion,
    tipo_propiedad,
    zona,
    presupuesto,
    dormitorios,
    lead_completo: lead_completo ? 'si' : 'no',
    historial,
    status: lead_completo ? 'calificado' : 'abierto',
  },
}];
